#!/bin/bash
set -e

# Deploy: WhatsApp visit confirmation (auto-send on visit creation + manual resend)
# Adds sendVisitConfirmationWhatsApp() to lib/whatsapp.js and wires it into
# createWalkInVisit() and checkInAppointment() in visits/actions.js, plus a
# resend button in visit-actions.js (per-row on the visits list).
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/whatsapp.js"
echo "Wrote lib/whatsapp.js"

mkdir -p "app/(main)/visits"
echo "" | base64 -d > "app/(main)/visits/actions.js"
echo "Wrote app/(main)/visits/actions.js"

mkdir -p "app/(main)/visits"
echo "" | base64 -d > "app/(main)/visits/visit-actions.js"
echo "Wrote app/(main)/visits/visit-actions.js"

git add lib/whatsapp.js "app/(main)/visits/actions.js" "app/(main)/visits/visit-actions.js"
git commit -m "Add WhatsApp visit confirmation (auto-send + manual resend)"
git push

echo "Done. Deployed WhatsApp visit confirmation integration."
